parameters.jsCode:
// Reglas Oficiales de Clasificación:
// 1. TMO <= límite -> APROBADO
// 2. TMO > límite -> REQUIERE REVISIÓN
// 3. Dato vacío o no válido -> ERROR DE DATOS

const configRows = $('Supabase - Leer Límite en app_settings').all();
let limite = 20.0;
let correoAlertas = 'andrescassiani46@gmail.com';

for (const r of configRows) {
  if (r.json.clave === 'tmo_limite_segundos') limite = parseFloat(r.json.valor_numerico);
  if (r.json.clave === 'correo_alertas_revision') correoAlertas = r.json.valor_texto;
}

const inputItems = $input.all();
let agentesList = [];

if (inputItems[0].json && inputItems[0].json.tmo_summaries) {
  agentesList = inputItems[0].json.tmo_summaries;
} else if (inputItems[0].json && inputItems[0].json.agentes) {
  agentesList = inputItems[0].json.agentes;
} else {
  agentesList = inputItems.map(i => i.json);
}

const aprobados = [];
const requiereRevision = [];
const errorDatos = [];

for (const row of agentesList) {
  const nombre = (row.nombre_agente || row.operador || row.agente || row.nombre || '').toString().trim();
  const rawTmo = (row.tmo_promedio_segundos !== undefined) ? row.tmo_promedio_segundos : (row.tmo || row.tmoPromedio || row['TMO Promedio']);
  const tmoVal = parseFloat(rawTmo);

  if (!nombre || isNaN(tmoVal) || tmoVal === null || tmoVal === undefined) {
    errorDatos.push({
      agente: nombre || 'DESCONOCIDO',
      tmo_promedio: null,
      limite: limite,
      clasificacion: 'ERROR DE DATOS',
      detalle: 'Tiempo de gestión vacío o formato no numérico'
    });
  } else if (tmoVal <= limite) {
    aprobados.push({
      agente: nombre,
      tmo_promedio: tmoVal,
      limite: limite,
      porcentaje_limite: Math.round((tmoVal / limite) * 10000) / 100,
      clasificacion: 'APROBADO'
    });
  } else {
    requiereRevision.push({
      agente: nombre,
      tmo_promedio: tmoVal,
      limite: limite,
      porcentaje_limite: Math.round((tmoVal / limite) * 10000) / 100,
      clasificacion: 'REQUIERE REVISIÓN'
    });
  }
}

return [{
  json: {
    limite_aplicado: limite,
    correo_alertas: correoAlertas,
    total_evaluados: agentesList.length,
    total_aprobados: aprobados.length,
    total_requiere_revision: requiereRevision.length,
    total_error_datos: errorDatos.length,
    lista_aprobados: aprobados,
    lista_requiere_revision: requiereRevision,
    lista_error_datos: errorDatos,
    todos_los_resultados: [...aprobados, ...requiereRevision, ...errorDatos]
  }
}];

